<script lang="ts">
 import {onMount} from 'svelte';import {api,upload,type Media} from './api';
 export let view:string;
 type Message={id:string;text:string;status:string;createdAt:string;author?:{username:string}};
 type Job={revision:number;status:string;attempts:number;error:string;updatedAt:string};
 let messages:Message[]=[],media:Media[]=[],jobs:Job[]=[],revision=0,configured=false,error='',busy=false,page=1,totalPages=1;
 async function load(){busy=true;error='';try{if(view==='messages'){const r=await api<{items:Message[];meta:{totalPages:number}}>(`/feedback/messages/admin?page=${page}`);messages=r.items;totalPages=r.meta.totalPages;}else if(view==='media')media=(await api<{items:Media[]}>('/media')).items;else{const result=await api<{revision:number;configured:boolean;items:Job[]}>('/mirror/status');jobs=result.items;revision=result.revision;configured=result.configured;}}catch(e){error=String(e);}finally{busy=false;}}
 onMount(load);
 async function moderate(id:string,status:string){try{await api(`/feedback/messages/admin/${id}/status`,'PATCH',{status});await load();}catch(e){error=String(e);}}
 async function uploadFiles(event:Event){busy=true;try{for(const file of (event.target as HTMLInputElement).files??[])await upload(file);await load();}catch(e){error=String(e);}finally{busy=false;}}
 async function remove(id:string){if(!confirm('将此图片移出媒体库？正在引用的图片无法移除。'))return;try{await api('/media/'+id,'DELETE');await load();}catch(e){error=String(e);}}
 async function retry(){try{await api('/mirror/retry','POST',{});await load();}catch(e){error=String(e);}}
 function displayName(name:string){try{return decodeURIComponent(name);}catch{return name;}}
 const statusNames:Record<string,string>={PENDING:'等待同步',DISPATCHED:'已触发构建',BUILDING:'构建中',COMPLETE:'线上版本已核实',FAILED:'失败',SUPERSEDED:'已由新版本替代'};
</script>
<section class="panel"><div class="section-head"><div><p class="eyebrow">{view==='messages'?'COMMUNITY':view==='media'?'LIBRARY':'PUBLISHING'}</p><h2>{view==='messages'?'留言审核':view==='media'?'媒体库':'镜像同步'}</h2></div><button disabled={busy} onclick={load}>刷新</button></div>
{#if error}<p class="error" role="alert">{error}</p>{/if}
{#if view==='messages'}<p class="muted">仅审核通过的留言公开展示。审核变更会同步到静态镜像。</p>{#each messages as message}<article class="message-row"><div><strong>{message.author?.username}</strong><p>{message.text}</p><small>{new Date(message.createdAt).toLocaleString('zh-CN')}</small></div><div><span class="badge">{message.status==='APPROVED'?'已通过':message.status==='REJECTED'?'已拒绝':'待审核'}</span><div class="toolbar"><button onclick={()=>moderate(message.id,'APPROVED')}>通过</button><button onclick={()=>moderate(message.id,'REJECTED')}>拒绝</button><button onclick={()=>moderate(message.id,'PENDING')}>待审核</button></div></div></article>{/each}{#if !messages.length&&!busy}<p class="empty">没有留言</p>{/if}<div class="pagination"><button disabled={page<=1} onclick={()=>{page--;void load();}}>上一页</button><span>{page}</span><button disabled={page>=totalPages} onclick={()=>{page++;void load();}}>下一页</button></div>
{:else if view==='media'}<label class="button primary">上传原图<input type="file" hidden accept="image/*" multiple disabled={busy} onchange={uploadFiles}/></label><p class="muted">支持 JPEG、PNG、WebP、GIF、AVIF，单张最多 20 MB。保留原图。</p><div class="photo-grid">{#each media as item}<article><img src={item.url+'?variant=thumb'} alt="" loading="lazy"/><strong>{displayName(item.name)}</strong><small>{(item.size/1024/1024).toFixed(2)} MB · {item.refs} 处引用</small><div class="toolbar"><button onclick={()=>navigator.clipboard.writeText(item.url)}>复制链接</button><a class="button" href={item.url} target="_blank" rel="noreferrer">原图</a><button disabled={item.refs>0} onclick={()=>remove(item.id)}>移除</button></div></article>{/each}</div>
{:else}<p>主站内容版本 <strong>#{revision}</strong></p>{#if !configured}<p class="notice">镜像自动同步尚未配置。配置完成后才能触发猫子云构建。</p>{/if}<button class="primary" disabled={busy||!configured} onclick={retry}>重新同步最新内容</button><p class="muted">只有检测到镜像线上版本与内容版本一致，才会显示同步完成。</p><div class="table-wrap"><table><thead><tr><th>版本</th><th>状态</th><th>更新时间</th><th>说明</th></tr></thead><tbody>{#each jobs as job}<tr><td>#{job.revision}</td><td>{statusNames[job.status]??job.status}</td><td>{new Date(job.updatedAt).toLocaleString('zh-CN')}</td><td>{job.error??'—'}</td></tr>{/each}</tbody></table></div>{/if}</section>
